"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function GraphCorners({ mark = "+" }: { mark?: string }) {
  const corner =
    "pointer-events-none absolute z-10 flex size-4 items-center justify-center bg-background font-mono text-sm leading-none text-graph-frame select-none"

  return (
    <>
      <span
        aria-hidden="true"
        className={cn(corner, "top-0 left-0 -translate-x-1/2 -translate-y-1/2")}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(corner, "top-0 right-0 translate-x-1/2 -translate-y-1/2")}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(
          corner,
          "bottom-0 left-0 -translate-x-1/2 translate-y-1/2"
        )}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(
          corner,
          "right-0 bottom-0 translate-x-1/2 translate-y-1/2"
        )}
      >
        {mark}
      </span>
    </>
  )
}

function GraphTitle({
  className,
  children,
  ...props
}: React.ComponentProps<"figcaption">) {
  return (
    <figcaption
      className={cn(
        "absolute top-0 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-background px-2.5 tracking-wide whitespace-nowrap uppercase",
        className
      )}
      {...props}
    >
      <span className="graph-title-ink text-graph-accent">[ {children} ]</span>
    </figcaption>
  )
}

function GraphBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("min-w-0 px-5 py-7 sm:px-8 sm:py-8", className)}
      {...props}
    />
  )
}

function GraphRule({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule w-full", className)}
      {...props}
    />
  )
}

function GraphRuleY({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule-y self-stretch", className)}
      {...props}
    />
  )
}

function GraphTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden="true"
      className={cn("flex w-full min-w-0 select-none", className)}
      {...props}
    />
  )
}

function GraphTick({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn("min-w-0 flex-1 overflow-hidden text-center", className)}
      {...props}
    />
  )
}

function Graph({
  title,
  corner = "+",
  className,
  children,
  ...props
}: React.ComponentProps<"figure"> & {
  title?: string
  corner?: string
}) {
  const captionId = React.useId()

  return (
    <figure
      aria-labelledby={title ? captionId : undefined}
      className={cn(
        "relative w-full min-w-0 graph-frame font-mono text-sm text-foreground",
        className
      )}
      {...props}
    >
      {title ? <GraphTitle id={captionId}>{title}</GraphTitle> : null}
      <GraphCorners mark={corner} />
      {children}
    </figure>
  )
}

export {
  Graph,
  GraphBody,
  GraphCorners,
  GraphRule,
  GraphRuleY,
  GraphTick,
  GraphTitle,
  GraphTrack,
}

import type { Transition, Variants } from "motion/react"

export const easeOutCubic = [0.215, 0.61, 0.355, 1] as const

export const DIM_OPACITY = 0.4

export function graphTransition(
  reduce: boolean | null,
  extras?: Transition
): Transition {
  if (reduce) {
    return { duration: 0 }
  }

  return {
    duration: 0.22,
    ease: easeOutCubic,
    ...extras,
  }
}

export function fadeUp(reduce: boolean | null): Variants {
  if (reduce) {
    return {
      hidden: { opacity: 1, transform: "translateY(0px)" },
      show: { opacity: 1, transform: "translateY(0px)" },
    }
  }

  return {
    hidden: { opacity: 0, transform: "translateY(8px)" },
    show: {
      opacity: 1,
      transform: "translateY(0px)",
      transition: graphTransition(false),
    },
  }
}

export function staggerList(reduce: boolean | null, stagger = 0.04): Variants {
  return {
    hidden: {},
    show: {
      transition: reduce ? { duration: 0 } : { staggerChildren: stagger },
    },
  }
}

export function fillDelay(reduce: boolean | null, index: number, step = 0.03) {
  if (reduce) {
    return 0
  }

  return Math.min(index * step, 0.28)
}

export function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

export const GLYPH_SETS = {
  shade: ["·", "░", "▒", "▓", "█"],
  ascii: [".", "-", "=", "#", "@"],
  hash: [".", ":", "+", "#", "█"],
  bar: ["▁", "▂", "▃", "▅", "█"],
} as const

export type GlyphSetName = keyof typeof GLYPH_SETS
export type Glyphs = GlyphSetName | readonly string[]

export const INTENSITY_GLYPHS = GLYPH_SETS.shade

export function resolveGlyphs(glyphs?: Glyphs): readonly string[] {
  if (glyphs == null) {
    return GLYPH_SETS.shade
  }

  if (typeof glyphs === "string") {
    return GLYPH_SETS[glyphs] ?? GLYPH_SETS.shade
  }

  return glyphs.length > 0 ? glyphs : GLYPH_SETS.shade
}

export function trackMarks(
  glyphs?: Glyphs,
  fallback: { empty: string; rest: string; fill: string } = {
    empty: "-",
    rest: "░",
    fill: "█",
  }
) {
  if (glyphs == null) {
    return fallback
  }

  const set = resolveGlyphs(glyphs)
  const last = set.length - 1

  return {
    empty: set[0] ?? fallback.empty,
    rest: set[Math.min(1, last)] ?? fallback.rest,
    fill: set[last] ?? fallback.fill,
  }
}

export function intensityLevel(value: number, max: number) {
  if (value <= 0 || max <= 0) {
    return 0
  }

  return Math.max(1, Math.round(clamp01(value / max) * 4))
}

export function intensityGlyph(
  level: number,
  glyphs: readonly string[] = INTENSITY_GLYPHS
) {
  if (glyphs.length === 0) {
    return "·"
  }

  const clamped = Math.min(4, Math.max(0, Math.round(level)))
  const index = Math.round((clamped / 4) * (glyphs.length - 1))
  return glyphs[index] ?? glyphs[0] ?? "·"
}

export function intensityClass(level: number, palette: GraphPalette = "mono") {
  const index = Math.min(4, Math.max(0, Math.round(level)))

  if (index <= 0) {
    return "text-graph-frame"
  }

  if (palette === "mono") {
    if (index <= 2) {
      return "text-graph-muted"
    }

    if (index === 3) {
      return "text-foreground"
    }

    return "text-graph-accent"
  }

  if (palette === "multi") {
    if (index === 1) {
      return "text-graph-accent-2"
    }

    if (index <= 3) {
      return "text-graph-accent-3"
    }

    return "text-graph-accent"
  }

  if (index <= 2) {
    return "text-graph-accent-2"
  }

  return "text-graph-accent"
}

export type GraphPalette = "mono" | "duo" | "multi"

const SERIES_TONES = [
  "text-graph-accent",
  "text-graph-accent-2",
  "text-graph-accent-3",
] as const

export function isMonoPalette(palette?: GraphPalette) {
  return palette == null || palette === "mono"
}

export function seriesClass(palette: GraphPalette | undefined, index: number) {
  if (isMonoPalette(palette)) {
    return index === 0 ? "text-graph-accent" : "text-foreground"
  }

  const count = palette === "duo" ? 2 : 3
  return SERIES_TONES[index % count]
}

export function seriesDim(
  palette: GraphPalette | undefined,
  highlighted: boolean
) {
  if (!isMonoPalette(palette) || highlighted) {
    return undefined
  }

  return { opacity: DIM_OPACITY }
}

export function toneClass(
  palette: GraphPalette | undefined,
  role: "primary" | "secondary" | "idle" | "empty"
) {
  if (role === "empty") {
    return "text-graph-frame"
  }

  if (role === "idle") {
    return "text-graph-muted"
  }

  if (role === "primary") {
    return "text-graph-accent"
  }

  return isMonoPalette(palette) ? "text-graph-muted" : "text-graph-accent-2"
}

"use client"

import { useEffect, useState } from "react"

export function parseInstant(value: Date | number | string) {
  if (value instanceof Date) {
    return value.getTime()
  }

  if (typeof value === "number") {
    return Number.isFinite(value) ? value : Number.NaN
  }

  return Date.parse(value)
}

export function pad2(value: number) {
  return String(Math.trunc(value)).padStart(2, "0")
}

export function formatHms(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000))
  const days = Math.floor(total / 86400)
  const hours = Math.floor((total % 86400) / 3600)
  const minutes = Math.floor((total % 3600) / 60)
  const seconds = total % 60
  const clock = `${pad2(hours)}:${pad2(minutes)}:${pad2(seconds)}`

  if (days > 0) {
    return `${days}d ${clock}`
  }

  return clock
}

export function formatAgo(ms: number) {
  const seconds = Math.max(0, Math.floor(ms / 1000))

  if (seconds < 60) {
    return `${seconds}s ago`
  }

  const minutes = Math.floor(seconds / 60)

  if (minutes < 60) {
    return `${minutes}m ago`
  }

  const hours = Math.floor(minutes / 60)

  if (hours < 48) {
    return `${hours}h ago`
  }

  return `${Math.floor(hours / 24)}d ago`
}

export function formatClock(ms: number) {
  const date = new Date(ms)

  return `${pad2(date.getHours())}:${pad2(date.getMinutes())}:${pad2(date.getSeconds())}`
}

export function useGraphNow(interval = 1000) {
  const [now, setNow] = useState<number | null>(null)

  useEffect(() => {
    setNow(Date.now())
    const id = window.setInterval(() => setNow(Date.now()), interval)
    return () => window.clearInterval(id)
  }, [interval])

  return now
}

"use client"

import { cn } from "@/lib/utils"

function GraphArrow({
  accent = false,
  stretch = false,
  className,
}: {
  accent?: boolean
  stretch?: boolean
  className?: string
}) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "flex min-w-6 items-center gap-1",
        stretch && "min-w-10 flex-1",
        accent ? "text-graph-accent" : "text-graph-frame",
        className
      )}
    >
      {stretch ? (
        <span className="h-px min-w-6 flex-1 border-t border-dashed border-current" />
      ) : (
        <span>- - -</span>
      )}
      <span className="shrink-0">▶</span>
    </div>
  )
}

export { GraphArrow }

"use client"

import type { ReactNode } from "react"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphRule,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type GraphAlign = "left" | "right"

function RuleY() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 left-0 graph-rule-y"
    />
  )
}

type GraphTableProps = {
  title: string
  headers: string[]
  rows: ReactNode[][]
  footer?: ReactNode[]
  align?: GraphAlign[]
  corner?: string
  className?: string
}

function GraphTable({
  title,
  headers,
  rows,
  footer,
  align,
  corner,
  className,
}: GraphTableProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.04)

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="px-3 py-6 sm:px-6 sm:py-8">
        <div className="@container graph-scroll-x">
          <table className="w-full min-w-lg border-separate border-spacing-0">
            <thead>
              <tr>
                {headers.map((header, index) => (
                  <th
                    key={header}
                    className={cn(
                      "relative px-3 pb-3 font-normal whitespace-nowrap text-foreground",
                      (align?.[index] ?? (index === 0 ? "left" : "right")) ===
                        "right"
                        ? "text-right"
                        : "text-left"
                    )}
                  >
                    {index > 0 ? <RuleY /> : null}
                    {header}
                  </th>
                ))}
              </tr>
              <tr>
                <th colSpan={headers.length} className="p-0">
                  <GraphRule />
                </th>
              </tr>
            </thead>
            <motion.tbody
              initial={reduce ? false : "hidden"}
              variants={list}
              viewport={{ once: true, amount: 0.4 }}
              whileInView="show"
            >
              {rows.map((row, rowIndex) => (
                <motion.tr key={rowIndex} variants={item}>
                  {row.map((cell, cellIndex) => (
                    <td
                      key={cellIndex}
                      className={cn(
                        "relative px-3 py-2.5 whitespace-nowrap",
                        (align?.[cellIndex] ??
                          (cellIndex === 0 ? "left" : "right")) === "right"
                          ? "text-right tabular-nums"
                          : "text-left"
                      )}
                    >
                      {cellIndex > 0 ? <RuleY /> : null}
                      {cell}
                    </td>
                  ))}
                </motion.tr>
              ))}
            </motion.tbody>
            {footer ? (
              <tfoot>
                <tr>
                  <td colSpan={headers.length} className="pt-2 pb-3">
                    <GraphRule />
                  </td>
                </tr>
                <tr>
                  {footer.map((cell, cellIndex) => (
                    <td
                      key={cellIndex}
                      className={cn(
                        "relative px-3 pt-1 whitespace-nowrap",
                        (align?.[cellIndex] ??
                          (cellIndex === 0 ? "left" : "right")) === "right"
                          ? "text-right tabular-nums"
                          : "text-left"
                      )}
                    >
                      {cellIndex > 0 ? <RuleY /> : null}
                      {cell}
                    </td>
                  ))}
                </tr>
              </tfoot>
            ) : null}
          </table>
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphTable }
export type { GraphTableProps }

"use client"

import type { ReactNode } from "react"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphRule,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type GraphAlign = "left" | "right"

type SheetSection = {
  title: string
  rows: ReactNode[][]
}

type GraphSheetProps = {
  title: string
  headers: string[]
  sections: SheetSection[]
  footer?: ReactNode[]
  align?: GraphAlign[]
  corner?: string
  className?: string
}

function side(align: GraphAlign[] | undefined, index: number): GraphAlign {
  return align?.[index] ?? (index === 0 ? "left" : "right")
}

function RuleY() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 left-0 graph-rule-y"
    />
  )
}

function GraphSheet({
  title,
  headers,
  sections,
  footer,
  align,
  corner,
  className,
}: GraphSheetProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.04)
  const columns = headers.length

  function cellClass(index: number, extra?: string) {
    return cn(
      "relative px-3 py-2.5",
      side(align, index) === "right" ? "text-right tabular-nums" : "text-left",
      extra
    )
  }

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="px-3 py-6 sm:px-6 sm:py-8">
        <div className="@container graph-scroll-x">
          <table className="w-full min-w-lg border-separate border-spacing-0">
            <thead>
              <tr>
                {headers.map((header, index) => (
                  <th
                    key={header}
                    className={cn(
                      "relative px-3 pb-3 font-normal whitespace-nowrap text-foreground",
                      side(align, index) === "right"
                        ? "text-right"
                        : "text-left"
                    )}
                  >
                    {index > 0 ? <RuleY /> : null}
                    {header}
                  </th>
                ))}
              </tr>
              <tr>
                <th colSpan={columns} className="p-0">
                  <GraphRule />
                </th>
              </tr>
            </thead>
            {sections.map((section, sectionIndex) => (
              <motion.tbody
                initial={reduce ? false : "hidden"}
                key={section.title}
                variants={list}
                viewport={{ once: true, amount: 0.4 }}
                whileInView="show"
              >
                {sectionIndex > 0 ? (
                  <tr>
                    <td colSpan={columns} className="pt-4 pb-1">
                      <GraphRule />
                    </td>
                  </tr>
                ) : null}
                <tr>
                  <td
                    className="px-3 pt-3 pb-1 text-graph-muted"
                    colSpan={columns}
                  >
                    {section.title}
                  </td>
                </tr>
                {section.rows.map((row, rowIndex) => (
                  <motion.tr key={rowIndex} variants={item}>
                    {row.map((cell, cellIndex) => (
                      <td
                        className={cellClass(cellIndex, "whitespace-nowrap")}
                        key={cellIndex}
                      >
                        {cellIndex > 0 ? <RuleY /> : null}
                        {cell}
                      </td>
                    ))}
                  </motion.tr>
                ))}
              </motion.tbody>
            ))}
            {footer ? (
              <tfoot>
                <tr>
                  <td colSpan={columns} className="pt-3 pb-3">
                    <GraphRule />
                  </td>
                </tr>
                <tr>
                  {footer.map((cell, cellIndex) => (
                    <td
                      className={cellClass(cellIndex, "whitespace-nowrap")}
                      key={cellIndex}
                    >
                      {cellIndex > 0 ? <RuleY /> : null}
                      {cell}
                    </td>
                  ))}
                </tr>
              </tfoot>
            ) : null}
          </table>
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphSheet }
export type { GraphAlign, GraphSheetProps, SheetSection }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass as paletteTone,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type FlowTone = "default" | "accent" | "muted"

type FlowNode = {
  label: string
  tone?: FlowTone
  stretch?: boolean
}

type FlowRow = {
  nodes: FlowNode[]
}

type GraphFlowProps = {
  title: string
  rows: FlowRow[]
  palette?: GraphPalette
  corner?: string
  className?: string
}

function nodeTone(palette: GraphPalette | undefined): Record<FlowTone, string> {
  return {
    default: "text-foreground",
    accent: paletteTone(palette, "primary"),
    muted: paletteTone(palette, "secondary"),
  }
}

function GraphFlow({
  title,
  rows,
  palette,
  corner,
  className,
}: GraphFlowProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.08)
  const tones = nodeTone(palette)

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-7">
        <motion.div
          className="flex flex-col gap-7"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.5 }}
          whileInView="show"
        >
          {rows.map((row, rowIndex) => (
            <motion.div
              key={rowIndex}
              className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2 sm:flex-nowrap"
              variants={item}
            >
              {row.nodes.map((node, nodeIndex) => {
                const tone = node.tone ?? "default"
                const live = tone === "accent"

                return (
                  <div
                    key={`${node.label}-${nodeIndex}`}
                    className={cn(
                      "flex min-w-0 items-center gap-3",
                      node.stretch && "min-w-16 flex-1"
                    )}
                  >
                    {nodeIndex > 0 ? (
                      <GraphArrow accent={live} stretch={node.stretch} />
                    ) : null}
                    <span
                      className={cn("shrink-0 whitespace-nowrap", tones[tone])}
                    >
                      {node.label}
                    </span>
                  </div>
                )
              })}
            </motion.div>
          ))}
        </motion.div>
      </GraphBody>
    </Graph>
  )
}

export { GraphFlow }
export type { FlowNode, FlowRow, GraphFlowProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fillDelay,
  graphTransition,
  toneClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type BarSeries = {
  label: string
  values: number[]
  size?: "sm" | "lg"
}

type GraphBarsProps = {
  title: string
  from: BarSeries
  to: BarSeries
  processor?: string
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function MiniBars({
  values,
  height,
  delay = 0,
  tone = "accent",
  fill,
  palette,
}: {
  values: number[]
  height: number
  delay?: number
  tone?: "accent" | "muted"
  fill: string
  palette?: GraphPalette
}) {
  const reduce = useReducedMotion()
  const max = Math.max(...values, 1)

  return (
    <div className="flex items-end gap-1">
      {values.map((value, index) => {
        const level = Math.round((value / max) * (height - 1))

        return (
          <span className="flex w-[1ch] flex-col justify-end" key={index}>
            {Array.from({ length: height }, (_, row) => {
              const fromBottom = height - 1 - row
              const on = fromBottom <= level

              return (
                <motion.span
                  className={cn(
                    "h-[1em] w-full text-center",
                    on
                      ? tone === "accent"
                        ? toneClass(palette, "primary")
                        : toneClass(palette, "secondary")
                      : "text-transparent"
                  )}
                  initial={reduce || !on ? false : { opacity: 0 }}
                  key={row}
                  transition={graphTransition(reduce, {
                    delay: delay + fillDelay(reduce, index, 0.03),
                  })}
                  viewport={{ once: true }}
                  whileInView={{ opacity: 1 }}
                >
                  {on ? fill : " "}
                </motion.span>
              )
            })}
          </span>
        )
      })}
    </div>
  )
}

function GraphBars({
  title,
  from,
  to,
  processor,
  glyphs,
  palette,
  corner,
  className,
}: GraphBarsProps) {
  const marks = trackMarks(glyphs)
  const fromHeight = from.size === "lg" ? 8 : 5
  const toHeight = to.size === "lg" ? 8 : 5

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody>
        <div className="flex flex-col items-center gap-8 sm:flex-row sm:items-end sm:justify-center sm:gap-8">
          <div className="flex flex-col items-center gap-3">
            <MiniBars
              delay={0.04}
              fill={marks.fill}
              height={fromHeight}
              palette={palette}
              tone="muted"
              values={from.values}
            />
            <p className={toneClass(palette, "secondary")}>{from.label}</p>
          </div>

          <div className="flex items-center justify-center gap-3 text-graph-muted max-sm:rotate-90">
            <GraphArrow />
            {processor ? <span>{processor}</span> : null}
            <GraphArrow />
          </div>

