"use client"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphRule,
  GraphTick,
  GraphTrack,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type WaterfallKind = "start" | "in" | "out" | "end"

type WaterfallItem = {
  label: string
  value: number
  display?: string
  kind?: WaterfallKind
}

type GraphWaterfallProps = {
  title: string
  items: WaterfallItem[]
  ticks?: number
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function resolveKind(
  item: WaterfallItem,
  index: number,
  length: number
): WaterfallKind {
  if (item.kind) {
    return item.kind
  }

  if (index === 0) {
    return "start"
  }

  if (index === length - 1) {
    return "end"
  }

  return item.value >= 0 ? "in" : "out"
}

function formatValue(item: WaterfallItem, kind: WaterfallKind) {
  if (item.display) {
    return item.display
  }

  const absolute = Math.abs(item.value)

  if (kind === "in") {
    return `+${absolute.toLocaleString("en-US")}`
  }

  if (kind === "out") {
    return `−${absolute.toLocaleString("en-US")}`
  }

  return item.value.toLocaleString("en-US")
}

function GraphWaterfall({
  title,
  items,
  ticks = 24,
  glyphs,
  palette,
  corner,
  className,
}: GraphWaterfallProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)
  const marks = trackMarks(glyphs)
  let run = 0
  const segments = items.map((entry, index) => {
    const kind = resolveKind(entry, index, items.length)
    const magnitude = Math.abs(entry.value)

    if (kind === "start") {
      const from = 0
      const to = entry.value
      run = entry.value
      return { ...entry, kind, from, to }
    }

    if (kind === "in") {
      const from = run
      const to = run + magnitude
      run = to
      return { ...entry, kind, from, to }
    }

    if (kind === "out") {
      const to = run
      const from = run - magnitude
      run = from
      return { ...entry, kind, from, to }
    }

    const total = entry.value
    run = total
    return { ...entry, kind, from: 0, to: total }
  })
  const lows = segments.map((segment) => Math.min(segment.from, segment.to))
  const highs = segments.map((segment) => Math.max(segment.from, segment.to))
  const low = Math.min(0, ...lows)
  const high = Math.max(1, ...highs)
  const span = high - low || 1

  function column(value: number) {
    return Math.round(((value - low) / span) * ticks)
  }

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-3">
        <motion.ul
          className="flex w-full flex-col gap-2"
          initial={reduce ? false : "hidden"}
          role="list"
          variants={list}
          viewport={{ once: true, amount: 0.4 }}
          whileInView="show"
        >
          {segments.map((segment, index) => {
            const start = Math.min(column(segment.from), column(segment.to))
            const end = Math.max(
              column(segment.from),
              column(segment.to),
              start + 1
            )
            const isEnd = segment.kind === "end"
            const showRule = isEnd && index > 0

            return (
              <li className="flex flex-col gap-2" key={segment.label}>
                {showRule ? <GraphRule /> : null}
                <motion.div
                  className="grid grid-cols-[minmax(0,7rem)_minmax(0,1fr)_minmax(0,5.5rem)] items-center gap-x-2 sm:gap-x-4"
                  variants={item}
                >
                  <span className="truncate text-foreground">
                    {segment.label}
                  </span>
                  <GraphTrack>
                    {Array.from({ length: ticks }, (_, cell) => {
                      const filled = cell >= start && cell < end
                      const tone = !filled
                        ? toneClass(palette, "empty")
                        : segment.kind === "out"
                          ? toneClass(palette, "secondary")
                          : segment.kind === "start"
                            ? "text-foreground"
                            : toneClass(palette, "primary")

                      return (
                        <GraphTick className={tone} key={cell}>
                          {filled ? marks.fill : marks.empty}
                        </GraphTick>
                      )
                    })}
                  </GraphTrack>
                  <span
                    className={cn(
                      "text-right tabular-nums",
                      segment.kind === "out" && toneClass(palette, "secondary"),
                      segment.kind === "end" && toneClass(palette, "primary"),
                      (segment.kind === "start" || segment.kind === "in") &&
                        "text-foreground"
                    )}
                  >
                    {formatValue(segment, segment.kind)}
                  </span>
                </motion.div>
              </li>
            )
          })}
        </motion.ul>
        <span className="sr-only">
          {segments
            .map(
              (segment) =>
                `${segment.label} ${formatValue(segment, segment.kind)}`
            )
            .join(", ")}
        </span>
      </GraphBody>
    </Graph>
  )
}

export { GraphWaterfall }
export type { GraphWaterfallProps, WaterfallItem, WaterfallKind }

"use client"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphTick,
  GraphTrack,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  resolveGlyphs,
  staggerList,
  toneClass,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type UptimeStatus = "ok" | "degraded" | "down" | "empty"

type GraphUptimeProps = {
  title: string
  days: UptimeStatus[]
  from?: string
  to?: string
  columns?: number
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function statusTone(
  palette: GraphPalette | undefined
): Record<UptimeStatus, string> {
  return {
    ok: toneClass(palette, "primary"),
    degraded: toneClass(palette, "secondary"),
    down: toneClass(palette, "empty"),
    empty: toneClass(palette, "empty"),
  }
}

function GraphUptime({
  title,
  days,
  from,
  to,
  columns = 30,
  glyphs,
  palette,
  corner,
  className,
}: GraphUptimeProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)
  const known = days.filter((day) => day !== "empty")
  const ok = known.filter((day) => day === "ok").length
  const percent = known.length === 0 ? 0 : Math.round((ok / known.length) * 100)
  const cols = Math.max(1, columns)
  const rows: UptimeStatus[][] = []
  const set = resolveGlyphs(glyphs)
  const last = set.length - 1
  const mark: Record<UptimeStatus, string> = {
    ok: set[last] ?? "█",
    degraded: set[Math.min(2, last)] ?? "▒",
    down: set[0] ?? "·",
    empty: "-",
  }
  const tone = statusTone(palette)

  for (let index = 0; index < days.length; index += cols) {
    rows.push(days.slice(index, index + cols))
  }

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col items-center gap-4">
        <div className="flex scrollbar-graph w-fit max-w-full flex-col gap-4 overflow-x-auto">
          <motion.div
            aria-hidden="true"
            className="flex flex-col gap-1 select-none"
            initial={reduce ? false : "hidden"}
            variants={list}
            viewport={{ once: true, amount: 0.4 }}
            whileInView="show"
          >
            {rows.map((row, rowIndex) => (
              <motion.div key={rowIndex} variants={item}>
                <GraphTrack className="w-auto justify-start gap-0.5">
                  {row.map((day, index) => (
                    <GraphTick
                      className={cn("flex-none", tone[day])}
                      key={`${rowIndex}-${index}`}
                    >
                      {mark[day]}
                    </GraphTick>
                  ))}
                </GraphTrack>
              </motion.div>
            ))}
          </motion.div>
          <div className="flex flex-wrap items-baseline justify-between gap-3">
            <p className={cn("tabular-nums", tone.ok)}>{percent}%</p>
            {from || to ? (
              <p className="flex gap-3 text-graph-muted">
                {from ? <span>{from}</span> : null}
                {to ? <span>{to}</span> : null}
              </p>
            ) : null}
          </div>
        </div>
        <p className="flex flex-wrap justify-center gap-x-4 gap-y-1 text-graph-muted">
          <span>
            <span className={tone.ok}>{mark.ok}</span> up
          </span>
          <span>
            <span className={tone.degraded}>{mark.degraded}</span> slow
          </span>
          <span>
            <span className={tone.down}>{mark.down}</span> down
          </span>
        </p>
        <span className="sr-only">
          {percent} percent uptime over {known.length} days
          {from && to ? `, ${from} to ${to}` : ""}
        </span>
      </GraphBody>
    </Graph>
  )
}

